export const MUSIC_TRACKS=Object.freeze([{id:'windowlight',title:'창가의 작은 빛',genre:'피아노 소품',mood:'따뜻한 건반과 느슨한 숨',seconds:43.64},{id:'pocket-kites',title:'주머니 속 연',genre:'스윙 재즈',mood:'통통 튀는 전자 건반과 리듬',seconds:36.92},{id:'afterglow-paperboats',title:'노을 종이배',genre:'앰비언트',mood:'느린 신시사이저와 맑은 울림',seconds:42.35},{id:'clover-waltz',title:'클로버 왈츠',genre:'포크 왈츠',mood:'세 박자 현악기 뜯는 소리',seconds:40},{id:'pixel-parade',title:'픽셀 행진',genre:'8비트 칩튠',mood:'경쾌한 펄스 음색과 전자 드럼',seconds:38.4}]);
const ids=new Set(MUSIC_TRACKS.map(t=>t.id)),roomTrack=id=>['playground','sportsField','homePlayroom'].includes(id)?'pocket-kites':['library','infirmary','science','math'].includes(id)?'afterglow-paperboats':'windowlight';
/** One gesture-owned AudioContext and at most one decoded music loop. */
export function createGameAudio({Audio=globalThis.AudioContext||globalThis.webkitAudioContext,fetch:load=globalThis.fetch,storage=null,onState=()=>{}}={}){
 let context=null,output=null,alive=true,enabled=false,room='courtyard',hidden=false,unlocked=false,current=null,request=0,listening=null,listeningVolume=.7,error='',pending=null;const blocks=new Set(),buffers=new Map();
 try{const saved=JSON.parse(storage?.getItem('dormi-audio-v1')??'null');enabled=saved?.enabled===true;}catch{}
 const state=()=>({enabled,unlocked,playing:current?.id??null,listening:listening?{...listening}:null,error});const notify=()=>onState(state());
 function stop(){request++;pending=null;if(current){const s=current;current=null;try{s.source.stop();}catch{}s.source.disconnect();s.gain.disconnect();}}
 function desired(){if(!alive||!unlocked||hidden)return null;if(listening)return listening.playing?{id:listening.id,kind:'listening',volume:listeningVolume}:null;return enabled&&!blocks.size?{id:roomTrack(room),kind:'bgm',volume:.30}:null;}
 function decode(id){if(!buffers.has(id)){const promise=load(new URL(`./music/${id}.mp3`,import.meta.url)).then(r=>{if(!r.ok)throw Error('MusicFetch');return r.arrayBuffer();}).then(b=>context.decodeAudioData(b)).catch(e=>{buffers.delete(id);throw e;});buffers.set(id,promise);}return buffers.get(id);}
 async function sync(){const want=desired();if(!want){stop();notify();return;}if(current?.id===want.id&&current.kind===want.kind){current.gain.gain.value=want.volume;notify();return;}const key=want.kind+':'+want.id;if(pending===key){try{await decode(want.id);}catch{}return;}stop();pending=key;const token=request;try{const buffer=await decode(want.id);if(!alive||token!==request||!desired()||desired().id!==want.id||desired().kind!==want.kind)return;const source=context.createBufferSource(),gain=context.createGain();source.buffer=buffer;source.loop=true;source.loopStart=0;source.loopEnd=buffer.duration;gain.gain.value=desired().volume;source.connect(gain);gain.connect(output);current={source,gain,id:want.id,kind:want.kind};pending=null;source.start();error='';notify();}catch{if(alive&&token===request){pending=null;error='음악을 열지 못했어요. 다시 재생해 주세요';notify();}}}
 async function unlock(){if(!alive)return null;if(!Audio){error='이 브라우저는 소리 재생을 지원하지 않아요';notify();return null;}try{if(!context){context=new Audio({latencyHint:'interactive'});const gain=context.createGain();gain.gain.value=.8;output=gain;const limiter=context.createDynamicsCompressor?.();if(limiter){gain.connect(limiter);limiter.connect(context.destination);}else gain.connect(context.destination);}await context.resume();if(!alive)return null;unlocked=context.state!=='suspended'&&context.state!=='closed';notify();return unlocked?{context,output}:null;}catch{error='소리가 준비되지 않았어요. 다시 눌러 주세요';notify();return null;}}
 notify();
 return{snapshot:state,unlock,async gesture(){if(!alive||!enabled||context?.state==='running')return;await unlock();await sync();},async setEnabled(value){enabled=!!value;try{storage?.setItem('dormi-audio-v1',JSON.stringify({enabled}));}catch{}if(enabled)await unlock();await sync();},setRoom(id){if(room===id)return;room=id;sync();},block(reason,value){value?blocks.add(reason):blocks.delete(reason);sync();},setHidden(value){hidden=!!value;if(hidden&&listening)listening.playing=false;sync();},async listen(id){if(!alive||!ids.has(id))return false;const selection={id,playing:true};listening=selection;stop();await unlock();if(!alive||listening!==selection)return false;await sync();return !!current&&current.id===id&&current.kind==='listening';},pauseListening(){if(listening)listening.playing=false;sync();},stopListening(){listening=null;stop();sync();},setListeningVolume(value){listeningVolume=Math.max(0,Math.min(1,Number(value)||0));sync();},dispose(){if(!alive)return;alive=false;stop();buffers.clear();output?.disconnect();context?.close?.();notify();}};
}
